from pathlib import Path

ROOT = Path(__file__).parent

CSS = r'''
*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font:14px/1.55 system-ui,-apple-system,"Segoe UI",sans-serif}button,input,select{font:inherit}button,select,input{min-height:44px}button,select{cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #3065db;outline-offset:2px}h1,h2,h3,p{margin:0}h1{font-size:25px;line-height:1.3;letter-spacing:-.02em}h2{font-size:17px}h3{font-size:15px}.muted{color:var(--sub)}.app{min-height:100vh;display:grid;grid-template-columns:210px minmax(0,1fr)}.sidebar{background:var(--nav);color:var(--navtext);padding:28px 18px}.brand{font-weight:750;font-size:18px;letter-spacing:-.03em;margin-bottom:42px}.nav-title{font-size:12px;color:var(--navmuted);margin:20px 10px 8px}.navitem{padding:11px 12px;border-radius:7px;color:var(--navmuted)}.navitem.active{background:var(--active);color:var(--navtext);font-weight:700}.navfoot{font-size:12px;line-height:1.6;margin:50px 10px;color:var(--navmuted)}.shell{min-width:0}.top{height:64px;padding:0 36px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);background:var(--surface);color:var(--sub)}.top strong{color:var(--ink)}main{max-width:1280px;margin:auto;padding:28px 36px 70px}.head{display:flex;justify-content:space-between;gap:24px;align-items:end;margin-bottom:24px}.head p{margin-top:6px;color:var(--sub)}.pill{display:inline-flex;align-items:center;gap:7px;border:1px solid var(--line);padding:6px 10px;border-radius:99px;white-space:nowrap;color:var(--sub);font-size:12px}.dot{width:7px;height:7px;border-radius:50%;background:#31704b}.intro{background:var(--intro);border:1px solid var(--line);border-radius:10px;padding:17px 20px;margin-bottom:20px;display:flex;justify-content:space-between;gap:18px}.intro p{color:var(--sub);margin-top:4px}.intro b{font-size:14px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:20px;align-items:start}.column{display:grid;gap:20px}.panel{background:var(--surface);border:1px solid var(--line);border-radius:10px;overflow:hidden}.panel-head{padding:20px 22px 15px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:16px;align-items:start}.panel-head p{font-size:13px;color:var(--sub);margin-top:3px}.panel-body{padding:20px 22px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:16px}.field{display:flex;flex-direction:column;gap:7px;min-width:0}.field.full{grid-column:1/-1}label{font-weight:650;font-size:13px}.hint{font-size:12px;color:var(--sub)}input,select{width:100%;border:1px solid var(--inputline);background:var(--surface);color:var(--ink);border-radius:7px;padding:9px 11px}input[readonly]{background:var(--intro);color:var(--sub)}.helper{margin-top:14px;color:var(--sub);font-size:13px}.cloud{padding:12px 14px;background:var(--intro);border-radius:7px;margin-top:14px}.cloud strong{display:block}.actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:20px}button{border:1px solid var(--inputline);border-radius:7px;background:var(--surface);color:var(--ink);padding:9px 15px;font-weight:650}button.primary{background:var(--accent);border-color:var(--accent);color:white}button:hover{filter:brightness(.95)}.save-note{color:var(--sub);font-size:12px}.badge{font-size:12px;color:var(--accent);background:var(--intro);padding:5px 9px;border-radius:5px;white-space:nowrap}.test-grid{display:grid;grid-template-columns:1fr auto;align-items:end;gap:12px}.status{margin-top:16px;border:1px solid var(--line);border-radius:7px;background:var(--intro);padding:14px 16px;min-height:64px}.status strong{display:block;margin-bottom:4px}.status p{color:var(--sub)}.scope{font-size:13px;color:var(--sub);margin-top:14px}.rule{border-top:1px solid var(--line);margin:18px 0}.fact{display:grid;grid-template-columns:72px 1fr;gap:8px;padding:11px 0;border-bottom:1px solid var(--line)}.fact:last-child{border:0}.fact span{color:var(--sub);font-size:13px}.fact b{font-size:13px;font-weight:600}.list{padding-left:18px;margin:12px 0 0;color:var(--sub)}.list li{margin:8px 0}.small{font-size:12px}.old{border-left:3px solid #a36b20;padding-left:14px}.old p{color:var(--sub);margin-top:6px;font-size:13px}.footer{color:var(--sub);margin-top:24px;font-size:12px}a{color:var(--accent)}
@media(max-width:850px){.app{display:block}.sidebar{padding:12px 18px;display:flex;align-items:center;gap:22px}.brand{margin:0}.sidebar .nav-title,.sidebar .navitem:not(.active),.navfoot{display:none}.top{height:52px;padding:0 18px}main{padding:22px 18px 48px}.layout{grid-template-columns:1fr}.head{align-items:start}.intro{display:block}.intro .pill{margin-top:12px}.panel-head,.panel-body{padding-left:17px;padding-right:17px}}@media(max-width:480px){body{font-size:16px}.fields{grid-template-columns:1fr}.field.full{grid-column:auto}.test-grid{grid-template-columns:1fr}.head{display:block}.head .pill{margin-top:12px}.top{font-size:12px}.panel-head{align-items:start}.intro{padding:15px}.actions button{width:100%}}
.panel,.panel-body,.column,.status,.status p,.fact b{min-width:0;overflow-wrap:anywhere}.save-note{overflow-wrap:anywhere}
'''

VARIANTS = [
 ('连接工作台','推荐方向 · 就地配置与验证',r'''body{--canvas:#f4f6fa;--ink:#202938;--sub:#526174;--surface:#fff;--nav:#f0f3f8;--navtext:#24334a;--navmuted:#53657b;--active:#dce7fb;--line:#dce3ec;--inputline:#a8b6c7;--intro:#f3f7ff;--accent:#2755cb}'''),
 ('模型验证台','方向二 · 把验证结果放在操作中心',r'''body{--canvas:#eaf0f1;--ink:#152e32;--sub:#435f62;--surface:#fff;--nav:#142e33;--navtext:#f4ffff;--navmuted:#b8d1cf;--active:#285057;--line:#cedddc;--inputline:#91aaa9;--intro:#eff8f5;--accent:#126c5d}.layout{grid-template-columns:300px minmax(0,1fr)}.primary-col{grid-column:2;grid-row:1}.secondary-col{grid-column:1;grid-row:1}.primary-col .test-panel{order:-1}.intro{border-left:5px solid var(--accent)}.panel{border-radius:3px}.head h1{font-size:29px}@media(max-width:850px){.layout{grid-template-columns:1fr}.primary-col,.secondary-col{grid-column:1;grid-row:auto}}'''),
 ('变更边界清单','方向三 · 先看变更，再进入配置',r'''body{--canvas:#f6f3ed;--ink:#272b31;--sub:#595f67;--surface:#fffefa;--nav:#ebe6dc;--navtext:#282d35;--navmuted:#5a6067;--active:#d8d0c0;--line:#ded9cf;--inputline:#a8a39a;--intro:#f3f0e9;--accent:#27485f}.sidebar{border-right:1px solid var(--line)}.layout{display:flex;flex-direction:column-reverse}.column{width:100%}.secondary-col{grid-template-columns:1fr 1fr}.primary-col{grid-template-columns:1fr 1fr;align-items:start}.panel{border-radius:2px}.head{border-bottom:2px solid var(--ink);padding-bottom:20px}.intro{border-radius:2px}.panel-head{border-bottom:1px solid var(--ink)}@media(max-width:850px){.secondary-col,.primary-col{grid-template-columns:1fr}}'''),
]

BODY = r'''
<div class="app"><aside class="sidebar" aria-label="布局示意"><div class="brand">GPT-Load <span class="small"> / 演示</span></div><div><div class="nav-title">管理</div><div class="navitem">概览</div><div class="navitem active">分组与连接</div><div class="navitem">调度</div><div class="navitem">请求日志</div><div class="navfoot">导航仅作布局示意<br>不是生产系统</div></div></aside><div class="shell"><div class="top"><strong>分组与连接</strong><span>需求探索 / 离线初稿</span></div><main>
<header class="head"><div><h1>如何减少渠道选择，又不丢失能力？</h1><p>新建连接探索 · TITLE</p></div><span class="pill"><span class="dot"></span> 本地模拟 · 不连接上游</span></header>
<div class="intro"><div><b>建议：常见场景先选 OpenAI Compatible</b><p>用连接类型收敛入口，不把不同 Provider 或协议视为等价。</p></div><span class="pill">概念方案，非现有功能</span></div>
<div class="layout"><div class="column primary-col">
<section class="panel"><div class="panel-head"><div><h2>连接配置</h2><p>填写示例，体验未来可能的配置方式</p></div><span class="badge">建议</span></div><div class="panel-body"><div class="fields">
<div class="field full"><label for="type">连接类型</label><select id="type"><option value="compatible">OpenAI Compatible</option><option value="azure">Azure OpenAI</option><option value="bedrock">Amazon Bedrock</option><option value="vertex">Vertex AI</option><option value="multi">其他 / 多协议</option></select><span class="hint">专用云鉴权、路由和协议差异仍保留独立入口。</span></div>
<div class="field"><label for="url">Base URL（演示）</label><input id="url" type="text" value="https://example.invalid/v1" autocomplete="off" spellcheck="false"></div><div class="field"><label for="key">演示 Key</label><input id="key" type="text" value="demo-key" readonly autocomplete="off"><span class="hint">固定假值，不可输入真实 Key。</span></div>
<div class="field full"><label for="model">模型名称</label><input id="model" type="text" placeholder="例如 example-model" autocomplete="off"><span class="hint">建议：模型发现不可用时允许手动填写；此演示不发现模型。</span></div></div>
<div class="cloud" id="cloud" hidden></div><p class="helper">这里只保存在当前页面内存中；刷新后重置。演示字段不发送、不连接网络。</p><div class="actions"><button class="primary" id="save" type="button">保存演示配置</button><span class="save-note" id="save-note" aria-live="polite">尚未保存</span>GOTO_TEST</div></div></section>
<section class="panel test-panel"><div class="panel-head"><div><h2>测试指定模型</h2><p>先保存演示配置，再运行模拟</p></div><span class="badge">模拟结果</span></div><div class="panel-body"><div class="test-grid"><div class="field"><label for="outcome">模拟结果</label><select id="outcome"><option value="passed">模拟通过</option><option value="failed">模拟失败</option><option value="unknown">模拟无法判断</option></select></div><button id="run" type="button">运行模拟测试</button></div><div class="status" role="status" aria-live="polite" id="result"><strong>尚未测试</strong><p>选择模型并保存后，可模拟查看不同结果。</p></div><p class="scope">现有 OpenAI Compatible 默认测活：仅指定模型的 Chat 非流式请求；其他专用渠道使用各自的探测预设。本演示无论选何种类型，均只模拟 Chat 非流式结果，不代表对应渠道的实际探测。一次通过不证明 Responses、工具调用或流式可用。</p></div></section>
</div><div class="column secondary-col"><section class="panel"><div class="panel-head"><div><h2>现状与建议</h2><p>分清已有能力与待讨论方案</p></div></div><div class="panel-body"><div class="fact"><span>现状</span><b>先选择渠道并保存模型，再从模型行发起测活；OpenAI Compatible 默认测指定模型 Chat 非流式，其他专用渠道有各自探测预设。</b></div><div class="fact"><span>建议</span><b>常见连接统一入口，并在测试时明确呈现实际探测范围。</b></div><div class="fact"><span>不代表</span><b>通过一次测试，即代表整个服务或所有协议兼容。</b></div></div></section>
<section class="panel"><div class="panel-head"><div><h2>保留边界</h2><p>精简入口不等于直接替换渠道</p></div></div><div class="panel-body"><div class="old"><b>旧组维持原配置与入口</b><p>建议兼容已有组，不静默迁移；此处只讨论界面方案，不承诺实现。</p></div><ul class="list"><li>Azure / Bedrock / Vertex 的专用鉴权和路由保留。</li><li>多协议能力保留入口；鉴权、操作、状态与调度需分别评估。</li><li>旧数据库不能原地打开；按现有离线转换流程处理，不等于自动兼容旧库。</li></ul></div></section></div></div><p class="footer">所有数据均为虚构示例 · 不持久化 · 不会发送请求 · 初稿仅用于选择方向</p></main></div></div>
'''

JS = r'''
const initial = { saved: null, dirty: true };
const state = { ...initial };
const $ = id => document.getElementById(id);
const getConfig = () => ({ type: $('type').value, url: $('url').value.trim(), model: $('model').value.trim() });
function validate(config) { if (!config.url || !config.model) return '请填写演示 Base URL 和模型名称后再保存。'; return ''; }
function resultFor(outcome, model) {
  if (outcome === 'passed') return ['模拟通过', `仅模拟 ${model} 的 Chat 非流式请求通过；不证明 Responses、工具调用或流式可用。`];
  if (outcome === 'failed') return ['模拟失败', `不等于协议不兼容；请检查凭据、地址、模型、限额或上游状态，再决定下一步。`];
  return ['模拟无法判断', '信息不足，无法判断连接或协议是否兼容；请检查网络、上游状态及错误详情后重试。'];
}
function renderResult(title, detail) { const root = $('result'); root.replaceChildren(); const strong = document.createElement('strong'); const p = document.createElement('p'); strong.textContent = title; p.textContent = detail; root.append(strong, p); }
function renderCloud() { const names = {azure:'Azure 专用配置入口',bedrock:'Bedrock 专用配置入口',vertex:'Vertex 专用配置入口',multi:'其他 / 多协议入口'}; const name = names[$('type').value]; $('cloud').hidden = !name; $('cloud').replaceChildren(); if(name){const strong=document.createElement('strong');strong.textContent=name;const text=document.createElement('span');text.textContent='这是保留入口的示意，专用凭据、区域、部署和协议细节需按实际能力单独设计。';$('cloud').append(strong,text);} }
$('type').addEventListener('change', renderCloud);
function markDirty() { state.dirty = true; $('save-note').textContent = '配置未保存'; if (state.saved) renderResult('模拟结果已过期', '配置已修改；请重新保存并运行模拟测试。'); }
for (const id of ['url', 'model']) $(id).addEventListener('input', markDirty);
$('type').addEventListener('change', markDirty);
$('save').addEventListener('click', () => { const config = getConfig(); const error = validate(config); if(error){$('save-note').textContent=error;renderResult('无法保存',error);return;} state.saved = config; state.dirty = false; $('save-note').textContent = '已保存在页面内存'; renderResult('已保存演示配置', '现在可以选择一种模拟结果。'); if ($('goto-test')) $('goto-test').hidden = false; });
if ($('goto-test')) $('goto-test').addEventListener('click', () => $('outcome').focus());
$('run').addEventListener('click', () => { if(!state.saved){renderResult('尚未保存', '请先填写模型并保存演示配置。');return;} if(state.dirty){renderResult('配置已修改', '请重新保存演示配置后再测试。');return;} renderResult(...resultFor($('outcome').value, state.saved.model)); });
'''

for idx, (title, subtitle, variant) in enumerate(VARIANTS, 1):
    goto = '<button id="goto-test" type="button" hidden>前往模拟测试</button>' if idx == 2 else ''
    html = '<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + title + ' · 渠道精简探索</title><style>' + CSS + variant + '</style></head><body>' + BODY.replace('TITLE', subtitle).replace('GOTO_TEST', goto) + '<script>' + JS + '</script></body></html>'
    (ROOT / f'dir-{idx}.html').write_text(html, encoding='utf-8')
